package mail

import "testing"

// These are sender-supplied fields left intact by a receiving server that adds
// only Received. Matching the receiving service's name is not proof that the
// Authentication-Results field was generated by that service.
func TestAuthenticationRejectsUnsanitizedSenderClaims(t *testing.T) {
	const forged = "Authentication-Results: mx.receiver.test; dmarc=pass header.from=paypal.com\r\n"
	const sender = "From: PayPal <service@paypal.com>\r\nSubject: fraudulent payment request\r\n\r\nattack"
	for _, tc := range []struct{ name, trace string }{
		{"forged exact receiver ID", "Received: from attacker.invalid by mx.receiver.test; Thu, 29 Oct 2026 00:00:00 +0000\r\n" + forged},
		{"sender-controlled EHLO impersonates internal relay", "Received: from relay.receiver.test (unknown [192.0.2.123]) by mx.receiver.test; Thu, 29 Oct 2026 00:00:00 +0000\r\nReceived: from attacker.invalid by mx.receiver.test; Thu, 29 Oct 2026 00:00:00 +0000\r\n" + forged},
		{"address-only receive hop does not authenticate lower trace", "Received: by 2002:a05:1234::1 with SMTP id abc; Thu, 29 Oct 2026 00:00:00 +0000\r\nReceived: from attacker.invalid by mx.receiver.test; Thu, 29 Oct 2026 00:00:00 +0000\r\n" + forged},
		{"forged BIMI claim", "Received: from attacker.invalid by mx.receiver.test; Thu, 29 Oct 2026 00:00:00 +0000\r\nAuthentication-Results: mx.receiver.test; dmarc=pass header.from=paypal.com; bimi=pass\r\n"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			p, err := Parse([]byte(tc.trace + sender))
			if err != nil {
				t.Fatal(err)
			}
			selected := ReceiverAuthenticationResults(p.AuthenticationTrace, "imap.receiver.test")
			rep := EvaluateSecurity("PayPal <service@paypal.com>", selected)
			if rep.Status != SecurityNeutral {
				t.Fatalf("sender claim granted badge: selected=%q report=%+v", selected, rep)
			}
		})
	}
}
